-- ============================================================================
-- REFRESH MEMOS — self-referencing lookups (see 02-create-functions.sql)
-- Generated by rulebook-to-postgres tool. Runs after the seed data. Each round
-- memoises the rows whose self-referenced parents are already memoised, so every
-- __compute call reads its parents from the memo. Rows on a genuine row cycle are
-- never ready and stay unmemoised (their wrapper falls back to __compute).
-- ============================================================================

CREATE OR REPLACE FUNCTION erb_refresh_memo_mobile_routes() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_mobile_routes_depth;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.mobile_route_id::text FROM mobile_routes c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_mobile_routes_depth m WHERE m.id = c.mobile_route_id::text)
      AND (c.parent_route IS NULL OR NOT EXISTS (SELECT 1 FROM mobile_routes p WHERE p.mobile_route_id = c.parent_route) OR EXISTS (SELECT 1 FROM erb_memo_mobile_routes_depth m WHERE m.id = c.parent_route::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_mobile_routes_depth(id, val) SELECT c.mobile_route_id::text, calc_mobile_routes_depth__compute(c.mobile_route_id) FROM mobile_routes c JOIN erb_memo_round r ON r.id = c.mobile_route_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memos() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM erb_refresh_memo_mobile_routes();
END $$;

SELECT erb_refresh_memos();
